sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* =========================================================
   VISAGUARDIAN AI
   SERVICE NOW SERVICE PORTAL WIDGET
   ========================================================= */


/* =========================================================
   MAIN PAGE
   ========================================================= */

.vg-app {
    width: 100%;
    min-height: 100vh;

    margin: 0;
    padding: 0 0 25px 0;

    box-sizing: border-box;

    color: #ffffff;

    font-family:
        "Segoe UI",
        Arial,
        Helvetica,
        sans-serif;

    background:
        radial-gradient(
            circle at 74% 23%,
            rgba(0, 95, 255, 0.17),
            transparent 29%
        ),

        radial-gradient(
            circle at 50% 90%,
            rgba(78, 0, 180, 0.12),
            transparent 35%
        ),

        linear-gradient(
            135deg,
            #020817 0%,
            #030d24 48%,
            #010611 100%
        );

    overflow: hidden;
}


/* =========================================================
   HEADER
   ========================================================= */

.vg-header {
    width: 100%;

    padding:
        27px 5% 12px;

    box-sizing: border-box;
}

.vg-brand {
    display: flex;

    align-items: center;

    gap: 13px;
}


/* SHIELD */

.vg-shield {
    width: 58px;
    height: 70px;

    position: relative;

    display: flex;

    align-items: center;

    justify-content: center;

    background:
        linear-gradient(
            145deg,
            #123d85,
            #03132d
        );

    border:
        2px solid #ffffff;

    clip-path:
        polygon(
            50% 0%,
            94% 18%,
            89% 69%,
            50% 100%,
            11% 69%,
            6% 18%
        );

    box-shadow:
        0 0 18px
        rgba(0, 132, 255, .65);
}

.vg-shield-inner {
    width: 43px;
    height: 51px;

    display: flex;

    align-items: center;

    justify-content: center;

    border:
        1px solid
        rgba(255,255,255,.85);

    clip-path:
        polygon(
            50% 0%,
            92% 18%,
            86% 68%,
            50% 100%,
            14% 68%,
            8% 18%
        );
}

.vg-globe-symbol {
    font-size: 30px;

    color: #4bb2ff;

    text-shadow:
        0 0 8px
        rgba(0,150,255,.8);
}


/* BRAND */

.vg-brand-text {
    display: flex;

    flex-direction: column;
}

.vg-brand-name {
    font-size: 28px;

    line-height: 1;

    font-weight: 700;

    letter-spacing:
        -0.6px;
}

.vg-brand-name span {
    color: #188fff;
}

.vg-brand-name strong {
    color: #9136ff;
}

.vg-tagline {
    margin-top: 7px;

    color: #d5dbe5;

    font-size: 15px;

    letter-spacing:
        .15px;
}


/* =========================================================
   HERO
   ========================================================= */

.vg-hero {
    width: 90%;

    max-width: 1400px;

    min-height: 375px;

    margin:
        10px auto 0;

    display: grid;

    grid-template-columns:
        46% 54%;

    align-items: center;
}


/* LEFT */

.vg-hero-left {
    position: relative;

    z-index: 10;

    padding-left: 3px;
}


/* PLATFORM */

.vg-platform {
    display: inline-flex;

    align-items: center;

    gap: 8px;

    padding:
        10px 18px;

    border:
        1px solid
        #087fff;

    border-radius:
        30px;

    color: #26b8ff;

    font-size: 15px;

    background:
        rgba(0, 88, 255, .05);

    box-shadow:
        0 0 15px
        rgba(0,120,255,.10);
}

.vg-star {
    font-size: 18px;

    color: #32aaff;
}


/* HEADING */

.vg-hero h1 {
    margin:
        25px 0 16px;

    font-size:
        clamp(
            44px,
            5vw,
            68px
        );

    line-height:
        1.04;

    letter-spacing:
        -2.5px;

    font-weight:
        750;
}

.vg-hero h1 span {
    display: block;

    background:
        linear-gradient(
            90deg,
            #1598ff 0%,
            #3b3cff 50%,
            #a42aff 100%
        );

    -webkit-background-clip:
        text;

    background-clip:
        text;

    -webkit-text-fill-color:
        transparent;
}


/* HERO DESCRIPTION */

.vg-hero-left p {
    margin: 0;

    color:
        #d1d8e5;

    font-size:
        18px;

    line-height:
        1.8;
}


/* =========================================================
   GLOBE SECTION
   ========================================================= */

.vg-hero-right {
    height: 430px;

    position: relative;

    display: flex;

    align-items: center;

    justify-content: center;
}


/* GLOW */

.vg-glow {
    position: absolute;

    width: 460px;
    height: 460px;

    border-radius:
        50%;

    background:
        radial-gradient(
            circle,
            rgba(0,110,255,.38),
            rgba(0,80,255,.10) 45%,
            transparent 72%
        );

    filter:
        blur(18px);
}


/* =========================================================
   GLOBE
   ========================================================= */

.vg-globe {
    width: 350px;
    height: 350px;

    position: relative;

    z-index: 5;

    border-radius:
        50%;

    background:
        radial-gradient(
            circle at 34% 27%,
            #075cb7 0%,
            #06376e 22%,
            #031b3d 50%,
            #010a1d 78%
        );

    border:
        2px solid
        #168cff;

    box-shadow:

        0 0 25px
        rgba(0,135,255,.85),

        0 0 70px
        rgba(0,100,255,.25),

        inset 0 0 55px
        rgba(0,119,255,.55);

    overflow: hidden;
}


/* GLOBE LIGHT */

.vg-globe-light {
    position: absolute;

    width: 150px;
    height: 150px;

    top: -40px;
    left: -25px;

    border-radius:
        50%;

    background:
        rgba(75,175,255,.2);

    filter:
        blur(30px);
}


/* LONGITUDE */

.vg-longitude {
    position: absolute;

    top: -3%;

    height: 106%;

    border:
        1px solid
        rgba(70,170,255,.32);

    border-radius:
        50%;
}

.vg-longitude-1 {
    width: 42%;

    left: 29%;
}

.vg-longitude-2 {
    width: 72%;

    left: 14%;
}

.vg-longitude-3 {
    width: 20%;

    left: 40%;
}


/* LATITUDE */

.vg-latitude {
    position: absolute;

    left: -3%;

    width: 106%;

    border:
        1px solid
        rgba(70,170,255,.32);

    border-radius:
        50%;
}

.vg-latitude-1 {
    height: 42%;

    top: 29%;
}

.vg-latitude-2 {
    height: 72%;

    top: 14%;
}

.vg-latitude-3 {
    height: 18%;

    top: 41%;
}


/* WORLD */

.vg-world {
    position: absolute;

    inset: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size:
        145px;

    opacity:
        .92;

    filter:
        drop-shadow(
            0 0 13px
            #008cff
        );
}


/* =========================================================
   ORBITS
   ========================================================= */

.vg-orbit {
    position: absolute;

    z-index: 3;

    width: 520px;
    height: 155px;

    border:
        1px solid
        rgba(38,157,255,.8);

    border-radius:
        50%;

    box-shadow:
        0 0 9px
        rgba(0,135,255,.35);
}

.vg-orbit-1 {
    transform:
        rotate(16deg);
}

.vg-orbit-2 {
    transform:
        rotate(-16deg);
}


/* ORBIT DOTS */

.vg-dot {
    position: absolute;

    z-index: 8;

    width: 6px;
    height: 6px;

    border-radius:
        50%;

    background:
        #38aaff;

    box-shadow:
        0 0 12px
        #008cff;
}

.dot-1 {
    top: 115px;
    right: 12%;
}

.dot-2 {
    top: 205px;
    right: 5%;
}

.dot-3 {
    bottom: 120px;
    left: 10%;
}

.dot-4 {
    top: 170px;
    left: 3%;
}


/* =========================================================
   PORTAL TITLE
   ========================================================= */

.vg-portal-title {
    width: 90%;

    max-width: 1400px;

    margin:
        0 auto 20px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    gap:
        25px;

    flex-wrap:
        wrap;
}

.vg-portal-title h2 {
    margin:
        0;

    font-size:
        32px;

    font-weight:
        700;
}

.vg-title-line {
    width:
        120px;

    height:
        1px;
}

.vg-line-left {
    background:
        linear-gradient(
            90deg,
            transparent,
            #0b71df
        );
}

.vg-line-right {
    background:
        linear-gradient(
            90deg,
            #0b71df,
            transparent
        );
}

.vg-portal-title p {
    width:
        100%;

    margin:
        -10px 0 0;

    text-align:
        center;

    color:
        #cbd4e2;

    font-size:
        16px;
}


/* =========================================================
   PORTAL CARDS
   ========================================================= */

.vg-portals {
    width:
        90%;

    max-width:
        1400px;

    margin:
        0 auto;

    display:
        grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap:
        22px;
}


/* CARD */

.vg-card {
    min-height:
        305px;

    padding:
        19px;

    box-sizing:
        border-box;

    border-radius:
        15px;

    text-align:
        center;

    display:
        flex;

    flex-direction:
        column;

    align-items:
        center;

    background:
        linear-gradient(
            145deg,
            rgba(7,29,62,.88),
            rgba(2,10,24,.96)
        );

    transition:
        transform .25s ease,
        box-shadow .25s ease;
}

.vg-card:hover {
    transform:
        translateY(-7px);
}


/* CARD COLORS */

.vg-student {
    border:
        1px solid
        #078cff;
}

.vg-advisor {
    border:
        1px solid
        #15db65;
}

.vg-admin {
    border:
        1px solid
        #a02cff;
}

.vg-officer {
    border:
        1px solid
        #ff8700;
}


/* =========================================================
   CARD ICON
   ========================================================= */

.vg-card-icon {
    width:
        100px;

    height:
        100px;

    margin-bottom:
        8px;

    border-radius:
        50%;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    font-size:
        46px;
}

.vg-student .vg-card-icon {
    border:
        1px solid
        #078cff;

    background:
        rgba(0,105,255,.10);
}

.vg-advisor .vg-card-icon {
    border:
        1px solid
        #15db65;

    background:
        rgba(0,180,80,.10);
}

.vg-admin .vg-card-icon {
    border:
        1px solid
        #a02cff;

    background:
        rgba(120,0,255,.10);
}

.vg-officer .vg-card-icon {
    border:
        1px solid
        #ff8700;

    background:
        rgba(255,120,0,.10);
}


/* =========================================================
   CARD TITLES
   ========================================================= */

.vg-card h3 {
    margin:
        0;

    font-size:
        26px;
}

.vg-student h3 {
    color:
        #1598ff;
}

.vg-advisor h3 {
    color:
        #40e777;
}

.vg-admin h3 {
    color:
        #a943ff;
}

.vg-officer h3 {
    color:
        #ff9b25;
}


/* DIVIDER */

.vg-card-divider {
    width:
        35px;

    height:
        2px;

    margin:
        7px 0 8px;
}

.vg-student .vg-card-divider {
    background:
        #1598ff;
}

.vg-advisor .vg-card-divider {
    background:
        #40e777;
}

.vg-admin .vg-card-divider {
    background:
        #a943ff;
}

.vg-officer .vg-card-divider {
    background:
        #ff9b25;
}


/* DESCRIPTION */

.vg-card p {
    max-width:
        290px;

    margin:
        0 auto 18px;

    color:
        #e1e7ef;

    font-size:
        15px;

    line-height:
        1.55;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.vg-button {
    width:
        100%;

    margin-top:
        auto;

    padding:
        15px 22px;

    box-sizing:
        border-box;

    border:
        none;

    border-radius:
        8px;

    color:
        #ffffff !important;

    text-decoration:
        none !important;

    font-size:
        16px;

    font-weight:
        600;

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    cursor:
        pointer;

    transition:
        all .2s ease;
}

.vg-button:hover {
    color:
        #ffffff !important;

    text-decoration:
        none !important;

    transform:
        translateY(-1px);

    filter:
        brightness(1.15);
}


/* STUDENT BUTTON */

.vg-student-button {
    background:
        linear-gradient(
            90deg,
            #0868e9,
            #084fc8
        );
}


/* ADVISOR */

.vg-advisor-button {
    background:
        linear-gradient(
            90deg,
            #12aa50,
            #07843c
        );
}


/* ADMIN */

.vg-admin-button {
    background:
        linear-gradient(
            90deg,
            #6419c7,
            #481095
        );
}


/* OFFICER */

.vg-officer-button {
    background:
        linear-gradient(
            90deg,
            #df7000,
            #b75400
        );
}


/* ARROW */

.vg-arrow {
    font-size:
        25px;

    font-weight:
        400;
}


/* =========================================================
   FEATURE BAR
   ========================================================= */

.vg-features {
    width:
        90%;

    max-width:
        1400px;

    margin:
        12px auto 0;

    padding:
        13px;

    box-sizing:
        border-box;

    display:
        grid;

    grid-template-columns:
        repeat(4, 1fr);

    border-radius:
        14px;

    background:
        rgba(4,19,43,.92);

    border:
        1px solid
        rgba(20,92,180,.16);
}


/* FEATURE */

.vg-feature {
    display:
        flex;

    align-items:
        center;

    gap:
        14px;

    padding:
        5px 18px;

    border-right:
        1px solid
        rgba(130,150,190,.2);
}

.vg-feature:last-child {
    border-right:
        none;
}


/* FEATURE ICON */

.vg-feature-icon {
    width:
        58px;

    min-width:
        58px;

    height:
        58px;

    border-radius:
        50%;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    font-size:
        26px;
}

.vg-blue-icon {
    border:
        1px solid
        #078cff;

    background:
        rgba(0,110,255,.10);
}

.vg-green-icon {
    border:
        1px solid
        #15db65;

    background:
        rgba(0,180,80,.10);
}

.vg-purple-icon {
    border:
        1px solid
        #a02cff;

    background:
        rgba(130,0,255,.10);
}

.vg-orange-icon {
    border:
        1px solid
        #ff8700;

    background:
        rgba(255,120,0,.10);
}


/* FEATURE TEXT */

.vg-feature-content h4 {
    margin:
        0 0 4px;

    font-size:
        16px;
}

.vg-feature:nth-child(1) h4 {
    color:
        #18a5ff;
}

.vg-feature:nth-child(2) h4 {
    color:
        #40e777;
}

.vg-feature:nth-child(3) h4 {
    color:
        #b34dff;
}

.vg-feature:nth-child(4) h4 {
    color:
        #ff9b25;
}

.vg-feature-content p {
    margin:
        0;

    color:
        #b8c2d2;

    font-size:
        13px;

    line-height:
        1.4;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1150px) {

    .vg-hero {
        grid-template-columns:
            1fr;
    }

    .vg-hero-left {
        text-align:
            center;
    }

    .vg-hero-left p {
        margin:
            auto;
    }

    .vg-hero-right {
        height:
            350px;
    }

    .vg-portals {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .vg-features {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .vg-feature:nth-child(2) {
        border-right:
            none;
    }

    .vg-feature:nth-child(-n+2) {
        border-bottom:
            1px solid
            rgba(130,150,190,.2);
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

    .vg-header {
        padding:
            20px;
    }

    .vg-brand-name {
        font-size:
            22px;
    }

    .vg-tagline {
        font-size:
            13px;
    }

    .vg-hero {
        width:
            92%;
    }

    .vg-hero h1 {
        font-size:
            42px;
    }

    .vg-hero-left p {
        font-size:
            16px;
    }

    .vg-globe {
        width:
            270px;

        height:
            270px;
    }

    .vg-glow {
        width:
            320px;

        height:
            320px;
    }

    .vg-orbit {
        width:
            370px;
    }

    .vg-portals {
        grid-template-columns:
            1fr;
    }

    .vg-features {
        grid-template-columns:
            1fr;
    }

    .vg-feature {
        border-right:
            none;

        border-bottom:
            1px solid
            rgba(130,150,190,.2);

        padding:
            14px;
    }

    .vg-feature:last-child {
        border-bottom:
            none;
    }
}
